const CFG = {"titulo": "Evento — Equipes", "resumo": false, "compacto": false, "secoes": [{"ref": "S1", "titulo": "Equipes (Teltonika)", "nota": "modem 4G: valor = sinal RSSI", "reserva": null, "porta": null}]};
/* NOC Evento - painel de FROTA (equipamentos por ping) - Business Text (afterRender)
 * O build injeta antes deste código:  const CFG = { titulo, resumo, secoes:[{ref, titulo, nota, reserva}] }
 * Cada seção é uma query (refId = sec.ref) trazendo, por host:
 *   "ICMP: disponível" (1/0), "ICMP: perda de pacotes" (%), "ICMP: tempo de resposta" (s),
 *   "Serviço TCP ...: disponível" (1/0, NVR/facial), "Modem: sinal (RSSI)" (dBm, Teltonika).
 * F = problemas (query de Problems) dos mesmos grupos.
 * CFG.resumo = true -> visão geral: um bloco por seção com contagem e lista do que está fora.
 */
const PERDA_ALERTA = 20, LATENCIA_ALERTA_MS = 150, ATRASO_MAX_MIN = 5, MAX_FORA_RESUMO = 14;

/* --- compatibilidade entre versões do plugin (igual ao NOC Servidores) --- */
const ctx = (typeof context !== "undefined") ? context : {};
const root0 = ctx.element || (typeof element !== "undefined" ? element : document);
const root = (root0.querySelector && root0.querySelector(".noc")) || root0;
const isFrames = a => Array.isArray(a) && a.length && a[0] && Array.isArray(a[0].fields);
function findSeries(o, depth, seen) {
  if (!o || typeof o !== "object" || depth > 4 || seen.has(o)) return null;
  seen.add(o);
  if (isFrames(o.series)) return o.series;
  if (isFrames(o)) return o;
  for (const k of ["panel", "panelData", "data", "series"]) { const r = findSeries(o[k], depth + 1, seen); if (r) return r; }
  return null;
}
const series = findSeries(ctx, 0, new Set())
  || (typeof panelData !== "undefined" ? findSeries(panelData, 0, new Set()) : null)
  || (typeof data !== "undefined" ? findSeries(data, 0, new Set()) : null) || [];

const esc = s => String(s == null ? "" : s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const vals = f => !f ? [] : (Array.isArray(f.values) ? f.values : (f.values && f.values.toArray ? f.values.toArray() : []));
const lastNN = arr => { for (let i = arr.length - 1; i >= 0; i--) if (arr[i] != null && !Number.isNaN(arr[i])) return arr[i]; return null; };
const seriesName = (fr, f) => { const c = f.config || {}; return c.displayNameFromDS || c.displayName || (f.state && f.state.displayName) || fr.name || f.name || ""; };
const hostOf = (f, name) => { const l = f.labels || {}; return l.host || l.host_name || (name.includes(": ") ? name.split(": ")[0] : name); };
const itemOf = (f, name) => { const l = f.labels || {}; return l.item || (name.includes(": ") ? name.split(": ").slice(1).join(": ") : name); };
const natural = (a, b) => a.localeCompare(b, "pt-BR", { numeric: true });

/* --- leitura --- */
const SEC = CFG.secoes.map(s => Object.assign({ hosts: {} }, s));
const SECBY = Object.fromEntries(SEC.map(s => [s.ref, s]));
let problems = [], newest = 0;
const debug = [];
for (const fr of series) {
  const ref = fr.refId || "";
  const tf = (fr.fields || []).find(f => f.type === "time");
  if (tf && ref !== "F") { const t = lastNN(vals(tf)); if (t > newest) newest = t; }
  for (const f of fr.fields || []) {
    const v = vals(f);
    debug.push(`[${ref}] frame="${fr.name || ""}" field="${f.name}" type=${f.type} labels=${JSON.stringify(f.labels || {})} n=${v.length}`);
    if (ref === "F") { if (v.length && typeof v[0] === "object" && v[0] !== null) problems = problems.concat(v); continue; }
    const sec = SECBY[ref]; if (!sec || f.type !== "number") continue;
    const name = seriesName(fr, f), h = hostOf(f, name), it = itemOf(f, name), x = lastNN(v);
    if (!h) continue;
    // host desabilitado no Zabbix (nome com "(desligado)") e sem coleta: não aparece; se voltar a pingar, aparece sozinho
    if (x == null && /\(desligado\)/i.test(h) && !sec.hosts[h]) continue;
    const o = sec.hosts[h] = sec.hosts[h] || { n: h, sec: sec.titulo, ping: null, loss: null, rtt: null, svc: null, svcN: "", rssi: null,
      res: !!(sec.reserva && new RegExp(sec.reserva).test(h)) };
    if (/ICMP: disponível|ICMP ping$/i.test(it)) o.ping = x;
    else if (/perda|loss/i.test(it)) o.loss = x;
    else if (/tempo de resposta|response time/i.test(it)) o.rtt = x;
    else if (/Serviço TCP/i.test(it)) { o.svc = x; const m = it.match(/TCP\s+(\d+)/); o.svcN = m ? m[1] : (sec.porta ? String(sec.porta) : ""); }
    else if (/RSSI|sinal/i.test(it)) o.rssi = x;
  }
}
const P = problems.map(p => {
  const hs = p.hosts && p.hosts[0];
  let ts = Number(p.timestamp || p.lastchange || p.clock || 0); if (ts > 1e12) ts = ts / 1000;
  const mt = p.suppressed == 1 || p.suppressed === "1" || p.maintenance === true || p.maintenance == 1 || !!(hs && hs.maintenance_status == 1);
  return { h: (hs && (hs.name || hs.host)) || p.host || "?", p: p.name || p.description || "", sev: Number(p.severity != null ? p.severity : p.priority) || 0, ts, mt };
});
const MAINT = new Set(P.filter(p => p.mt).map(p => p.h));
const ALL = SEC.flatMap(s => Object.values(s.hosts));
const PA = P.filter(p => !p.mt && ALL.some(h => h.n === p.h && !h.res));

if (!ALL.length) {
  root.innerHTML = `<div class="dbg">${esc(CFG.titulo)}: nenhum equipamento nas queries.\nConfira o datasource e se os grupos existem no Zabbix.\n\n${esc(debug.join("\n") || "Nenhum dado recebido.")}</div>`;
  return;
}

/* --- estado --- */
const SEV = ["Not classified", "Information", "Warning", "Average", "High", "Disaster"];
const SEVC = ["#6b7280", "#38bdf8", "#f5b301", "#fb923c", "#ef4444", "#b91c1c"];
const ms = s => s == null ? null : s * 1000;
function state(o) {
  if (o.res) return "res";
  if (MAINT.has(o.n)) return "maint";
  if (o.ping === 0) return "crit";
  if (o.ping == null) return "unk";
  if (o.svc === 0) return "crit";
  if ((o.loss != null && o.loss >= PERDA_ALERTA) || (o.rtt != null && ms(o.rtt) >= LATENCIA_ALERTA_MS)) return "warn";
  if (PA.some(p => p.h === o.n && p.sev >= 2)) return "warn";
  return "ok";
}
function motivo(o, st) {
  if (st === "res") return "reserva";
  if (st === "maint") return "manutenção";
  if (o.ping === 0) return "FORA";
  if (o.ping == null) return "sem dados";
  if (o.svc === 0) return o.svcN ? "porta " + o.svcN : "serviço";
  if (o.loss != null && o.loss >= PERDA_ALERTA) return "perda " + Math.round(o.loss) + "%";
  if (o.rssi != null) return Math.round(o.rssi) + " dBm";
  return o.rtt != null ? Math.round(ms(o.rtt)) + " ms" : "";
}
ALL.forEach(o => { o.st = state(o); o.mo = motivo(o, o.st); });
const ord = { crit: 0, warn: 1, unk: 2, maint: 3, ok: 4, res: 5 };
const conta = arr => { const a = arr.filter(o => o.st !== "res" && o.st !== "maint");
  return { n: a.length, on: a.filter(o => o.ping === 1).length, fora: a.filter(o => o.st === "crit").length,
           deg: a.filter(o => o.st === "warn").length, unk: a.filter(o => o.st === "unk").length,
           res: arr.filter(o => o.st === "res").length, mt: arr.filter(o => o.st === "maint").length }; };

/* --- KPIs --- */
const T = conta(ALL), hi = PA.filter(p => p.sev >= 4).length;
const lat = ALL.filter(o => o.ping === 1 && o.rtt != null && !o.res).map(o => ms(o.rtt));
const latAvg = lat.length ? Math.round(lat.reduce((a, b) => a + b, 0) / lat.length) : null;
const pctOn = T.n ? Math.round(T.on / T.n * 100) : 0;
const K = [
  ["Online", `${T.on}<span> / ${T.n}</span>`, T.fora ? "crit" : T.on < T.n ? "warn" : "ok", `${pctOn}% da frota${T.mt ? ` · ${T.mt} em manutenção` : ""}`],
  ["Fora do ar", T.fora, T.fora ? "crit" : "ok", "sem ping ou serviço parado"],
  ["Degradados", T.deg, T.deg ? "warn" : "ok", `perda ≥ ${PERDA_ALERTA}% ou latência ≥ ${LATENCIA_ALERTA_MS} ms`],
  ["Sem dados", T.unk, T.unk ? "warn" : "ok", "ainda sem coleta"],
  CFG.compacto && SEC.length
    ? (() => { const c0 = conta(Object.values(SEC[0].hosts)); return [`${SEC[0].titulo} fora`, c0.fora, c0.fora ? "crit" : "ok", SEC[0].nota || `${c0.on}/${c0.n} online`]; })()
    : ["Latência média", latAvg == null ? "—" : `${latAvg}<span> ms</span>`, latAvg != null && latAvg >= LATENCIA_ALERTA_MS ? "warn" : "", "dos equipamentos online"],
  ["Problemas ativos", PA.length, hi ? "crit" : PA.length ? "warn" : "ok", `${hi} High/Disaster`]
];

/* --- seções --- */
const curto = n => n.replace(/_mylaps$/i, "").replace(/^NVR-DVR-/i, "NVR ").replace(/^ACESSO-CARRETA-/i, "CARRETA ")
  .replace(/\s*\((sem SNMP|desligado|ICX[^)]*)\)/i, "").replace(/^SW Intelbras\s+/i, "INT ").replace(/^SW Ruckus\s+/i, "RKS ")
  .replace(/^AP[- ]10\.0\.0\./i, "AP .").replace(/^(CAM|ACESSO|NVR|SW)-SEDE-/i, "$1 ").replace(/\b10\.0\.(\d+\.\d+)\b/, "$1");
const tile = o => `<div class="tl ${o.st}${o.st === "crit" && o.ping === 1 ? " porta" : ""}" data-n="${esc(o.n)}" title="${esc(o.n)}"><span class="tn">${esc(curto(o.n))}</span><span class="tm">${esc(o.mo)}</span></div>`;
const secHtml = (CFG.resumo ? [...SEC].sort((a, b) => (!Object.keys(a.hosts).length) - (!Object.keys(b.hosts).length)) : SEC).map(s => {
  const hs = Object.values(s.hosts).sort((a, b) => ord[a.st] - ord[b.st] || natural(a.n, b.n)), c = conta(hs);
  const cls = !hs.length ? "vazio" : c.fora ? "crit" : (c.deg || c.unk) ? "warn" : "ok";
  const head = `<div class="sh2"><b>${esc(s.titulo)}</b><span class="cnt ${cls}">${hs.length ? `${c.on}/${c.n} online` : "sem equipamentos"}</span>
    ${c.fora ? `<span class="tag crit">${c.fora} fora</span>` : ""}${c.deg ? `<span class="tag warn">${c.deg} degradado(s)</span>` : ""}
    ${c.unk ? `<span class="tag unk">${c.unk} sem dados</span>` : ""}${c.res ? `<span class="tag res">${c.res} reserva</span>` : ""}
    ${s.nota ? `<span class="nota">${esc(s.nota)}</span>` : ""}</div>`;
  if (!hs.length) return `<section class="sec vazio">${head}<div class="nk-empty">Nenhum host neste grupo no Zabbix ainda.</div></section>`;
  if (CFG.resumo) {
    const fora = hs.filter(o => o.st === "crit" || o.st === "warn");
    const pc = c.n ? Math.round(c.on / c.n * 100) : 0;
    return `<section class="sec rs ${cls}">${head}<div class="rbar"><div class="rfill ${cls}" style="width:${pc}%"></div></div>
      <div class="tiles">${fora.slice(0, MAX_FORA_RESUMO).map(tile).join("")}${fora.length > MAX_FORA_RESUMO ? `<div class="tl mais">+${fora.length - MAX_FORA_RESUMO}</div>` : ""}
      ${!fora.length ? `<div class="okmsg">✓ tudo respondendo</div>` : ""}</div></section>`;
  }
  return `<section class="sec ${cls}">${head}<div class="tiles">${hs.map(tile).join("")}</div></section>`;
}).join("");

/* --- fila de atenção --- */
const age = ts => { if (!ts) return ""; let s = Math.floor(Date.now() / 1000 - ts); const d = Math.floor(s / 86400), h = Math.floor(s % 86400 / 3600), m = Math.floor(s % 3600 / 60); return d ? `${d}d ${h}h` : h ? `${h}h ${m}m` : `${m}m`; };
const Q = [...PA].sort((a, b) => b.sev - a.sev || b.ts - a.ts);
const queueHtml = Q.length ? Q.map(p => `<li data-n="${esc(p.h)}"><span class="bar" style="background:${SEVC[p.sev] || SEVC[0]}"></span>
  <div><div class="h">${esc(p.h)}</div><div class="p"><span class="sev" style="color:${SEVC[p.sev] || SEVC[0]}">${SEV[p.sev] || ""}</span>${esc(p.p)}</div></div><span class="t">${age(p.ts)}</span></li>`).join("")
  : `<li class="empty">Nenhum problema ativo.</li>`;

/* --- dados atrasados --- */
const fmtH = t => new Date(t).toLocaleTimeString("pt-BR");
const atrasoMin = newest ? (Date.now() - newest) / 60000 : null;
const staleHtml = atrasoMin != null && atrasoMin > ATRASO_MAX_MIN
  ? `<div class="stale">⚠ DADOS ATRASADOS — última coleta recebida às ${fmtH(newest)} (há ${Math.round(atrasoMin)} min). Verifique o Zabbix server e o datasource.</div>` : "";

root.innerHTML = `${staleHtml}<div class="topbar"><span class="${staleHtml ? "bad" : ""}">● ${esc(CFG.titulo)} · ${newest ? "dados de " + fmtH(newest) : "sem timestamp"}</span><span>tela renderizada às ${fmtH(Date.now())}</span></div>
  <section class="kpis">${K.map(k => `<div class="kpi ${k[2]}"><div class="l">${k[0]}</div><div class="v">${k[1]}</div><div class="s">${k[3]}</div></div>`).join("")}</section>
  <div class="main"><div class="secs ${CFG.resumo ? "resumo" : ""} ${CFG.compacto ? "compacto" : ""}">${secHtml}</div>
    <aside class="side"><div class="box"><h2>Atenção <span class="c ${Q.length ? "" : "z"}">${Q.length}</span></h2><ul class="q">${queueHtml}</ul></div>
      <div class="box legend"><h2>Legenda</h2><div class="lg"><span class="tl ok"><span class="tn">OK</span></span><span class="tl warn"><span class="tn">degradado</span></span>
      ${CFG.compacto ? `<span class="tl crit"><span class="tn">sem ping</span></span><span class="tl crit porta"><span class="tn">porta fechada</span></span>` : `<span class="tl crit"><span class="tn">fora / porta</span></span>`}<span class="tl unk"><span class="tn">sem dados</span></span><span class="tl res"><span class="tn">reserva</span></span></div></div></aside></div>`;

/* --- detalhe no hover --- */
const row = (k, v) => `<div class="nk-row"><span>${k}</span><span>${v}</span></div>`;
const COL = { crit: "#ef4444", warn: "#f5b301", ok: "#22c55e", unk: "#64748b", maint: "#6b7280", res: "#475569" };
const LBL = { crit: "FORA", warn: "ALERTA", ok: "OK", unk: "SEM DADOS", maint: "MANUTENÇÃO", res: "RESERVA" };
function detail(o) {
  const pr = P.filter(p => p.h === o.n).sort((a, b) => b.sev - a.sev);
  return `<div class="nk-head" style="border-color:${COL[o.st]}"><div><b>${esc(o.n)}</b><div class="nk-sub">${esc(o.sec)}</div></div>
    <span class="badge" style="background:${COL[o.st]}">${LBL[o.st]}</span></div>
    <div class="nk-sec"><div class="nk-t">Rede</div>
      ${row("Ping", o.ping === 1 ? "responde" : o.ping === 0 ? "SEM RESPOSTA" : "—")}
      ${row("Perda de pacotes", o.loss == null ? "—" : Math.round(o.loss) + "%")}
      ${row("Latência", o.rtt == null ? "—" : ms(o.rtt).toFixed(1) + " ms")}
      ${o.svc != null ? row(o.svcN ? "Porta " + esc(o.svcN) : "Serviço", o.svc === 1 ? "aberta" : "FECHADA") : ""}
      ${o.rssi != null ? row("Sinal 4G (RSSI)", Math.round(o.rssi) + " dBm") : ""}</div>
    <div class="nk-sec"><div class="nk-t">Problemas ativos (${pr.length})</div>
      ${pr.length ? pr.map(p => `<div class="nk-pr"><span class="sev" style="color:${SEVC[p.sev] || SEVC[0]}">${SEV[p.sev] || ""}</span>${esc(p.p)}<span class="nk-age">${age(p.ts)}</span></div>`).join("") : `<div class="nk-empty">Nenhum</div>`}</div>`;
}
root.style.position = "relative";
let tip = root.querySelector(".nk-card");
if (!tip) { tip = document.createElement("div"); tip.className = "nk-card"; root.appendChild(tip); }
let tipFor = null;
root.onmousemove = e => {
  const c = e.target.closest(".tl[data-n], .q li[data-n]");
  if (!c) { tip.style.display = "none"; tipFor = null; return; }
  const o = ALL.find(x => x.n === c.dataset.n); if (!o) { tip.style.display = "none"; return; }
  if (tipFor !== o.n) { tip.innerHTML = detail(o); tipFor = o.n; }
  tip.style.display = "block";
  const r = root.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let vx = e.clientX + 18, vy = e.clientY + 12;
  if (vx + tw > innerWidth - 8) vx = e.clientX - tw - 18;
  if (vx < 8) vx = 8;
  if (vy + th > innerHeight - 8) vy = innerHeight - 8 - th;
  if (vy < 8) vy = 8;
  tip.style.left = (vx - r.left + root.scrollLeft) + "px";
  tip.style.top = (vy - r.top + root.scrollTop) + "px";
};
root.onmouseleave = () => { tip.style.display = "none"; tipFor = null; };

options.styles:
.noc{--line:#223049;--ink:#e6edf7;--ink2:#9fb0c8;--mute:#64748b;--ok:#22c55e;--warn:#f5b301;--crit:#ef4444;--accent:#38bdf8;--bar:#3b82f6;color:var(--ink);font:13px/1.35 "Segoe UI",Roboto,Arial,sans-serif;min-height:100%;overflow:visible;position:relative}
.noc *{box-sizing:border-box}
.noc .kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-bottom:12px}
.noc .kpi{background:#111827;border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:6px;padding:8px 10px}
.noc .kpi .l{font-size:10px;color:var(--ink2);text-transform:uppercase;letter-spacing:.6px}
.noc .kpi .v{font:700 24px/1.1 Consolas,monospace;margin-top:2px}
.noc .kpi .v span{font-size:13px;color:var(--ink2);font-weight:400}
.noc .kpi .s{font-size:10px;color:var(--mute)}
.noc .kpi.ok{border-left-color:var(--ok)}.noc .kpi.warn{border-left-color:var(--warn)}.noc .kpi.crit{border-left-color:var(--crit)}
.noc .main{display:grid;grid-template-columns:1fr 340px;gap:12px}
.noc .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px;align-content:start}
.noc .card{background:#141c2b;border:1px solid var(--line);border-top:3px solid var(--ok);border-radius:6px;padding:8px 10px;cursor:pointer}
.noc .card:hover{border-color:var(--accent)}
.noc .card.warn{border-top-color:var(--warn)}.noc .card.crit{border-top-color:#fb923c}.noc .card.crit .dot{background:#fb923c}.noc .card.crit .issue{background:rgba(251,146,60,.16);color:#fdba74}
.noc .card.down{border-top-color:var(--crit);background:#1d1418}.noc .card.down .dot{background:var(--crit)}.noc .card.down .issue{background:rgba(239,68,68,.18);color:#fca5a5}
.noc .card.focus{outline:2px solid var(--accent)}
.noc .ch{display:flex;align-items:center;gap:6px;font-weight:600;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.noc .dot{width:8px;height:8px;border-radius:50%;flex:none;background:var(--ok)}
.noc .warn .dot{background:var(--warn)}.noc .crit .dot{background:var(--crit)}
.noc .sub{font-size:10px;color:var(--mute);margin:1px 0 6px}
.noc .issue{font-size:10px;font-weight:600;padding:2px 6px;border-radius:3px;margin-bottom:6px;display:inline-block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.noc .warn .issue{background:rgba(245,179,1,.15);color:#fcd34d}.noc .crit .issue{background:rgba(239,68,68,.18);color:#fca5a5}
.noc .m{display:grid;grid-template-columns:44px 1fr 42px;align-items:center;gap:6px;font-size:11px;margin:3px 0}
.noc .m .n{color:var(--ink2)}.noc .m .val{text-align:right;font-family:Consolas,monospace}
.noc .track{height:6px;background:#1f2a3d;border-radius:3px;overflow:hidden}
.noc .fill{height:100%;border-radius:3px;background:var(--bar)}
.noc .fill.w{background:var(--warn)}.noc .fill.c{background:var(--crit)}
.noc .foot{display:flex;justify-content:space-between;font-size:10px;color:var(--mute);margin-top:6px;border-top:1px solid var(--line);padding-top:5px}
.noc .off .val,.noc .off .track{opacity:.35}
.noc .side{display:flex;flex-direction:column;gap:12px}
.noc .box{background:#111827;border:1px solid var(--line);border-radius:6px}
.noc .box h2{margin:0;padding:8px 10px;font-size:12px;display:flex;justify-content:space-between;border-bottom:1px solid var(--line)}
.noc .box h2 .c{background:var(--crit);color:#fff;border-radius:10px;padding:0 7px;font-size:11px}
.noc .box h2 .c.z{background:var(--ok)}
.noc .q{list-style:none;margin:0;padding:0;max-height:320px;overflow:auto}
.noc .q li{display:grid;grid-template-columns:4px 1fr auto;gap:8px;padding:7px 10px;border-bottom:1px solid var(--line);cursor:pointer}
.noc .q li:hover{background:#18233a}
.noc .q .bar{border-radius:2px}.noc .q .h{font-weight:600;font-size:12px}.noc .q .p{font-size:11px;color:var(--ink2)}
.noc .q .t{font-size:10px;color:var(--mute);white-space:nowrap}
.noc .q .empty{display:block;padding:10px;color:var(--mute)}
.noc .sev{font-size:9px;font-weight:700;text-transform:uppercase;margin-right:4px}
.noc .spot{padding:10px}
.noc .spot .title{display:flex;justify-content:space-between;align-items:center}
.noc .spot .title b{font-size:16px}
.noc .badge{font-size:10px;font-weight:700;padding:2px 7px;border-radius:3px;color:#000}
.noc .spot table{width:100%;border-collapse:collapse;margin-top:8px;font-size:11px}
.noc .spot td{padding:3px 0;border-bottom:1px solid var(--line)}.noc .spot td:last-child{text-align:right;font-family:Consolas,monospace}
.noc .dbg{font:11px Consolas,monospace;color:#fcd34d;white-space:pre-wrap;background:#111827;padding:10px;border:1px solid var(--line);border-radius:6px}
@media (max-width:1100px){.noc .main{grid-template-columns:1fr}.noc .kpis{grid-template-columns:repeat(3,1fr)}}
.noc .spot table,.noc .spot tr,.noc .spot td{border:0!important;background:transparent!important}
.noc .spot td{border-bottom:1px solid var(--line)!important;padding:3px 0!important}

.noc .nk-card{position:absolute;z-index:50;display:none;width:360px;pointer-events:none;background:#0f172a;border:1px solid #2b3b57;border-radius:8px;box-shadow:0 12px 32px rgba(0,0,0,.6);font-size:11px;overflow:hidden}
.noc .nk-head{display:flex;justify-content:space-between;align-items:flex-start;gap:8px;padding:10px 12px;border-left:4px solid;background:#111b2e}
.noc .nk-head b{font-size:14px}.noc .nk-sub{color:var(--mute);font-size:10px;margin-top:2px}
.noc .nk-sec{padding:8px 12px;border-top:1px solid var(--line)}
.noc .nk-t{font-size:9px;text-transform:uppercase;letter-spacing:.7px;color:var(--ink2);margin-bottom:5px}
.noc .nk-row{display:flex;justify-content:space-between;padding:2px 0}.noc .nk-row span:last-child{font-family:Consolas,monospace}
.noc .nk-res{display:grid;grid-template-columns:90px 1fr;align-items:center;gap:8px;margin-bottom:4px}
.noc .nk-res span{display:block;color:var(--ink2);font-size:10px}.noc .nk-res b{font:700 16px Consolas,monospace}
.noc .nk-res b.w{color:var(--warn)}.noc .nk-res b.c{color:var(--crit)}
.noc .nk-spark{width:100%;height:28px;display:block}
.noc .nk-empty{color:var(--mute);font-size:10px}
.noc .nk-disk{display:grid;grid-template-columns:120px 1fr 40px;align-items:center;gap:6px;margin:3px 0}
.noc .nk-disk span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.noc .nk-disk span:last-child{text-align:right;font-family:Consolas,monospace}
.noc .nk-pr{padding:2px 0;display:flex;gap:4px;align-items:baseline}.noc .nk-age{margin-left:auto;color:var(--mute);white-space:nowrap}

.noc .disks .m{margin:2px 0;font-size:10px}.noc .disks .track{height:5px}
.noc .m .n{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.noc .nk-card{max-height:calc(100vh - 16px);overflow-y:auto}

.noc .fwl{display:flex;justify-content:space-between;font-size:11px;margin:3px 0}.noc .fwl span{color:var(--ink2)}.noc .fwl b{font:600 11px Consolas,monospace}
.noc .fwl b.okc{color:var(--ok)}.noc .fwl b.bad{color:var(--crit)}
.noc .nk-if{display:grid;grid-template-columns:10px 1fr 80px 80px;gap:6px;align-items:center;margin:2px 0}
.noc .nk-if span:nth-child(2){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.noc .nk-if span:nth-child(n+3){text-align:right;font-family:Consolas,monospace}
.noc .nk-if .d{width:7px;height:7px;border-radius:50%;background:var(--mute)}.noc .nk-if .d.up{background:var(--ok)}.noc .nk-if .d.dn{background:var(--crit)}

.noc .stale{background:#7f1d1d;border:1px solid var(--crit);color:#fff;font-weight:700;padding:10px 14px;border-radius:6px;margin-bottom:8px;animation:nocblink 1.6s infinite}
@keyframes nocblink{50%{opacity:.75}}
.noc .topbar{display:flex;justify-content:space-between;font-size:10px;color:var(--mute);margin-bottom:6px}.noc .topbar .bad{color:var(--crit);font-weight:700}
.noc .sites{background:#111827;border:1px solid var(--line);border-radius:6px;padding:8px 10px;margin-bottom:12px}
.noc .sites .sh{display:flex;gap:10px;align-items:baseline;font-size:12px;margin-bottom:6px}.noc .sites .sh span{color:var(--ink2);font-size:11px}.noc .sites .sh em{color:var(--warn);font-style:normal}
.noc .chips{display:flex;flex-wrap:wrap;gap:6px}
.noc .chip{display:flex;align-items:center;gap:6px;background:#141c2b;border:1px solid var(--line);border-left:3px solid var(--ok);border-radius:4px;padding:4px 8px;font-size:11px}
.noc .chip.warn{border-left-color:var(--warn)}.noc .chip.crit{border-left-color:var(--crit);background:#1d1418}.noc .chip.unk{border-left-color:var(--mute)}
.noc .chip .dot{width:7px;height:7px}.noc .chip.unk .dot{background:var(--mute)}
.noc .chip .sn{font-weight:600}.noc .chip .sm{color:var(--ink2);font-family:Consolas,monospace;font-size:10px}.noc .chip .sm.hot{color:var(--warn);font-weight:700}
.noc .card.maint{border-top-color:#6b7280;opacity:.6}.noc .card.maint .dot{background:#6b7280}
.noc .card.maint .issue{background:rgba(107,114,128,.25);color:#cbd5e1}
.noc .q li.mt{opacity:.55}.noc .mtag{font-size:9px;font-weight:600;background:#374151;color:#cbd5e1;border-radius:3px;padding:0 5px;margin-left:4px}

.noc .dmore{font-size:10px;color:var(--mute);text-align:right;margin-top:1px}

/* --- frota (equipamentos por ping) --- */
.noc .secs{display:flex;flex-direction:column;gap:10px;min-width:0}
.noc .sec{background:#111827;border:1px solid var(--line);border-left:4px solid var(--ok);border-radius:6px;padding:8px 10px}
.noc .sec.warn{border-left-color:var(--warn)}.noc .sec.crit{border-left-color:var(--crit)}.noc .sec.vazio{border-left-color:var(--mute);opacity:.7}
.noc .sh2{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:8px;font-size:13px}
.noc .sh2 .cnt{font:700 12px Consolas,monospace;color:var(--ink2)}
.noc .sh2 .cnt.crit{color:#fca5a5}.noc .sh2 .cnt.warn{color:#fcd34d}.noc .sh2 .cnt.ok{color:#86efac}
.noc .tag{font-size:10px;font-weight:700;padding:1px 6px;border-radius:3px}
.noc .tag.crit{background:rgba(239,68,68,.2);color:#fca5a5}.noc .tag.warn{background:rgba(245,179,1,.18);color:#fcd34d}
.noc .tag.unk{background:#1f2937;color:#94a3b8}.noc .tag.res{background:#1f2937;color:#94a3b8}
.noc .nota{font-size:10px;color:var(--mute);margin-left:auto}
.noc .tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:4px}
.noc .tl{display:flex;flex-direction:column;justify-content:center;min-height:34px;padding:3px 6px;border-radius:4px;background:#13261c;border:1px solid #1d3b2a;border-left:3px solid var(--ok);cursor:default;overflow:hidden}
.noc .tl .tn{font-size:11px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.noc .tl .tm{font:10px Consolas,monospace;color:var(--ink2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.noc .tl.warn{background:#2a2410;border-color:#4a3d10;border-left-color:var(--warn)}
.noc .tl.crit{background:#3a1418;border-color:#6b1d24;border-left-color:var(--crit);animation:nocblink 1.6s infinite}
.noc .tl.crit .tm{color:#fecaca;font-weight:700}
.noc .tl.unk{background:#151b26;border-color:#232c3b;border-left-color:var(--mute)}.noc .tl.unk .tn{color:#94a3b8}
.noc .tl.maint,.noc .tl.res{background:#141821;border-color:#1f2633;border-left-color:#475569;opacity:.55}
.noc .tl.mais{align-items:center;font-weight:700;color:var(--ink2);background:#151b26;border-left-color:var(--mute)}
.noc .tl:hover{outline:1px solid var(--accent)}
.noc .resumo{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:10px}
.noc .rbar{height:8px;background:#1f2a3d;border-radius:4px;overflow:hidden;margin-bottom:8px}
.noc .rfill{height:100%;background:var(--ok)}.noc .rfill.warn{background:var(--warn)}.noc .rfill.crit{background:var(--crit)}
.noc .okmsg{grid-column:1/-1;color:#86efac;font-size:12px;padding:4px 0}
.noc .legend .lg{display:flex;flex-wrap:wrap;gap:4px;padding:8px 10px}.noc .legend .tl{min-height:22px;animation:none}
/* modo compacto (tela CFTV + acesso: centenas de equipamentos numa tela) */
.noc .compacto .tiles{grid-template-columns:repeat(auto-fill,minmax(66px,1fr));gap:3px}
.noc .compacto .tl{min-height:20px;padding:2px 5px;border-left-width:2px}
.noc .compacto .tl .tn{font-size:10px}
.noc .compacto .tl .tm{display:none}
.noc .compacto .tl.crit{animation:none}
.noc .compacto .tl.crit .tn{color:#fecaca}
.noc .compacto .sec{padding:6px 8px}.noc .compacto .sh2{margin-bottom:5px}
.noc .tl.crit.porta{background:repeating-linear-gradient(135deg,#3a1418 0 6px,#2a1014 6px 12px);border-style:dashed;border-left-style:solid}
